import{_ as a,o,c as t,ae as e}from"./chunks/framework.Dzr56EFm.js";const m=JSON.parse('{"title":"产品发布 - 2026-05-08","description":"","frontmatter":{"date":"2026-05-08T00:00:00.000Z","category":"Product"},"headers":[],"relativePath":"daily/2026-05-08-product.md","filePath":"daily/2026-05-08-product.md"}'),n={name:"daily/2026-05-08-product.md"};function s(i,r,g,p,l,h){return o(),t("div",null,[...r[0]||(r[0]=[e('<h1 id="产品发布-2026-05-08" tabindex="-1">产品发布 - 2026-05-08 <a class="header-anchor" href="#产品发布-2026-05-08" aria-label="Permalink to &quot;产品发布 - 2026-05-08&quot;">​</a></h1><blockquote><p>AI App、工具、浏览器、搜索、Copilot</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日产品发布领域主要动态包括Figma推出AI网站创建工具和批量营销素材功能，AI副驾驶通过大型语言模型提升工作效率，OpenAI发布SearchGPT搜索引擎，以及Product Copilot作为AI助手集成在Jira和Confluence中。最值得关注的是Figma的AI工具更新和OpenAI的SearchGPT搜索引擎，它们分别代表了设计工具和搜索引擎领域的创新。</p><hr><h3 id="_1-figma发布新的ai工具-用于创建网站和应用程序" tabindex="-1">1. Figma发布新的AI工具，用于创建网站和应用程序 <a class="header-anchor" href="#_1-figma发布新的ai工具-用于创建网站和应用程序" aria-label="Permalink to &quot;1. Figma发布新的AI工具，用于创建网站和应用程序&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://techcrunch.com/2025/05/07/figma-releases-new-ai-powered-tools-for-creating-sites-app-prototypes-and-marketing-assets/" target="_blank" rel="noreferrer">Figma releases new AI-powered tools for creating sites, app ...</a></p><p><strong>一句话摘要</strong>: Figma推出AI网站创建工具和批量生成营销素材功能</p><p><strong>能解决什么问题</strong>: 设计师和营销人员需要快速创建网站和营销素材</p><p><strong>产品应用</strong>: 适用于需要快速原型设计和营销素材制作的企业</p><p><strong>示例场景</strong>: 设计师使用Figma Sites创建并发布网站</p><hr><h3 id="_2-2026年ai副驾驶-定义与工作原理" tabindex="-1">2. 2026年AI副驾驶：定义与工作原理 <a class="header-anchor" href="#_2-2026年ai副驾驶-定义与工作原理" aria-label="Permalink to &quot;2. 2026年AI副驾驶：定义与工作原理&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://aisera.com/blog/what-is-ai-copilot/" target="_blank" rel="noreferrer">AI Copilots: What They Are and How They Work in 2026</a></p><p><strong>一句话摘要</strong>: AI副驾驶通过大型语言模型提升工作效率和问题解决能力。</p><p><strong>能解决什么问题</strong>: 解决耗时耗力的任务自动化和复杂问题的历史数据分析。</p><p><strong>产品应用</strong>: 可应用于企业系统整合，自动化复杂任务，提升员工和客户满意度。</p><p><strong>示例场景</strong>: Aisera企业AI副驾驶集成多系统，实现无缝协作。</p><hr><h3 id="_3-数字新闻关注-openai推出自家搜索引擎" tabindex="-1">3. 数字新闻关注：OpenAI推出自家搜索引擎 <a class="header-anchor" href="#_3-数字新闻关注-openai推出自家搜索引擎" aria-label="Permalink to &quot;3. 数字新闻关注：OpenAI推出自家搜索引擎&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://modo25.com/news-insights/digital-news-to-watch-openai-launches-new-search-engine/" target="_blank" rel="noreferrer">Digital News To Watch: Open AI launches its own search engine. | Modo25</a></p><p><strong>一句话摘要</strong>: OpenAI发布SearchGPT搜索引擎，直接回答查询而非提供链接列表。</p><p><strong>能解决什么问题</strong>: 解决传统搜索引擎提供链接列表而非直接答案的问题。</p><p><strong>产品应用</strong>: 可应用于提升用户体验，通过直接提供答案简化信息检索过程。</p><p><strong>示例场景</strong>: 用户查询天气，SearchGPT直接给出温度和天气状况。</p><hr><h3 id="_4-产品副驾驶——软件产品团队的ai助手" tabindex="-1">4. 产品副驾驶——软件产品团队的AI助手 <a class="header-anchor" href="#_4-产品副驾驶——软件产品团队的ai助手" aria-label="Permalink to &quot;4. 产品副驾驶——软件产品团队的AI助手&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://product-copilot.ai/" target="_blank" rel="noreferrer">Product Copilot – AI Assistant for Software Product Teams</a></p><p><strong>一句话摘要</strong>: Product Copilot是集成在Jira和Confluence中的AI助手，帮助产品团队提高工作效率。</p><p><strong>能解决什么问题</strong>: 解决产品团队在创建清晰任务、回答疑问、清理待办事项和更新文档时的效率问题。</p><p><strong>产品应用</strong>: 适用于任何使用Jira和Confluence的产品团队，通过浏览器扩展直接集成。</p><p><strong>示例场景</strong>: 产品负责人无需切换标签和复制粘贴，直接在Jira中使用Product Copilot创建和管理用户故事。</p><hr><h3 id="_5-figma产品新闻和发布说明" tabindex="-1">5. Figma产品新闻和发布说明 <a class="header-anchor" href="#_5-figma产品新闻和发布说明" aria-label="Permalink to &quot;5. Figma产品新闻和发布说明&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/release-notes/" target="_blank" rel="noreferrer">Figma product news and release notes</a></p><p><strong>一句话摘要</strong>: Figma新增功能，提升设计和图像编辑效率。</p><p><strong>能解决什么问题</strong>: 提高设计师和开发者在创建和编辑图像时的效率。</p><p><strong>产品应用</strong>: 适用于需要快速生成和编辑图像的实际产品设计中。</p><p><strong>示例场景</strong>: 开发者使用FigJam直接从代码生成架构图。</p><hr><h3 id="_6-figma-make向所有用户开放" tabindex="-1">6. Figma Make向所有用户开放 <a class="header-anchor" href="#_6-figma-make向所有用户开放" aria-label="Permalink to &quot;6. Figma Make向所有用户开放&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/blog/figma-make-general-availability/" target="_blank" rel="noreferrer">Figma Make Is Now Available to All Users</a></p><p><strong>一句话摘要</strong>: Figma Make及其AI功能结束测试，正式向所有用户开放。</p><p><strong>能解决什么问题</strong>: 提供更广泛的设计工具和AI功能，增强用户的设计能力。</p><p><strong>产品应用</strong>: 适用于产品设计、UI/UX设计等领域，提升设计效率和质量。</p><p><strong>示例场景</strong>: 设计师使用Figma Make快速迭代设计原型。</p><hr><h3 id="_7-遇见figma-ai-为设计师提供智能工具" tabindex="-1">7. 遇见Figma AI：为设计师提供智能工具 <a class="header-anchor" href="#_7-遇见figma-ai-为设计师提供智能工具" aria-label="Permalink to &quot;7. 遇见Figma AI：为设计师提供智能工具&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.figma.com/blog/introducing-figma-ai/" target="_blank" rel="noreferrer">Meet Figma AI: Empowering Designers with Intelligent Tools | Figma Blog</a></p><p><strong>一句话摘要</strong>: Figma AI在测试期间免费，旨在提高设计师工作效率。</p><p><strong>能解决什么问题</strong>: 解决设计师寻找真实内容和快速定位设计元素的难题。</p><p><strong>产品应用</strong>: 可以应用到产品设计中，通过AI生成内容和搜索功能提升效率。</p><p><strong>示例场景</strong>: 设计师使用AI工具快速生成真实文案和图像。</p><hr><h3 id="_8-什么是副驾驶以及它的工作原理-微软副驾驶" tabindex="-1">8. 什么是副驾驶以及它的工作原理？| 微软副驾驶 <a class="header-anchor" href="#_8-什么是副驾驶以及它的工作原理-微软副驾驶" aria-label="Permalink to &quot;8. 什么是副驾驶以及它的工作原理？| 微软副驾驶&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.microsoft.com/en-us/microsoft-copilot/copilot-101/what-is-copilot" target="_blank" rel="noreferrer">What Is a Copilot and How Does It Work? | Microsoft Copilot</a></p><p><strong>一句话摘要</strong>: 副驾驶通过AI辅助功能优化工作流程，提高生产力。</p><p><strong>能解决什么问题</strong>: 解决手动、耗时任务，提升工作效率和决策质量。</p><p><strong>产品应用</strong>: 可应用于实际产品，如自动化客户管理、财务和供应链管理。</p><p><strong>示例场景</strong>: 零售商使用副驾驶优化库存预测。</p><hr><h3 id="_9-figma-ai工具向所有用户推出的发布日期" tabindex="-1">9. Figma AI工具向所有用户推出的发布日期 <a class="header-anchor" href="#_9-figma-ai工具向所有用户推出的发布日期" aria-label="Permalink to &quot;9. Figma AI工具向所有用户推出的发布日期&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://forum.figma.com/ask-the-community-7/release-date-for-ai-tool-rollout-to-all-users-26131" target="_blank" rel="noreferrer">Release Date for AI Tool Rollout to All Users? | Figma Forum</a></p><p><strong>一句话摘要</strong>: Figma AI工具仍在有限测试阶段，全面推出日期尚未确定。</p><p><strong>能解决什么问题</strong>: 解决设计师在UI/UX设计中的自动化和效率问题。</p><p><strong>产品应用</strong>: 可应用于产品设计流程，提高设计效率和质量。</p><p><strong>示例场景</strong>: 设计师使用Figma AI自动生成界面布局。</p><hr><h3 id="_10-ai副驾驶能做什么-顶级好处和用例" tabindex="-1">10. AI副驾驶能做什么？顶级好处和用例 <a class="header-anchor" href="#_10-ai副驾驶能做什么-顶级好处和用例" aria-label="Permalink to &quot;10. AI副驾驶能做什么？顶级好处和用例&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://www.moveworks.com/us/en/resources/blog/what-does-an-ai-copilot-do" target="_blank" rel="noreferrer">What does an AI copilot do? The top benefits and use cases</a></p><p><strong>一句话摘要</strong>: AI副驾驶通过智能支持提升工作效率。</p><p><strong>能解决什么问题</strong>: 解决工作效率低下和重复性任务处理问题。</p><p><strong>产品应用</strong>: 可应用于客户服务、密码重置、审批管理等场景。</p><p><strong>示例场景</strong>: 客服副驾驶快速解决常规查询，释放人力处理复杂问题。</p><hr>',75)])])}const d=a(n,[["render",s]]);export{m as __pageData,d as default};
